"""Native Alpha Zoo applicability audit and causal minute-frequency adapters."""
from __future__ import annotations

import ast
import re
from typing import Any

import numpy as np
import pandas as pd
from src.factors.base import delta, safe_div, ts_mean, ts_std
from src.factors.registry import get_default_registry

_UNSUPPORTED_NOTES = re.compile(r"degraded|proxy|approximat|not\s+implemented", re.IGNORECASE)
_CROSS_SECTIONAL = {"rank", "zscore", "scale", "indneutralize", "zscore_by_group"}


def _cross_sectional_calls(source: str) -> list[str]:
    tree = ast.parse(source)
    aliases = {}
    for node in ast.walk(tree):
        if isinstance(node, ast.ImportFrom):
            for imported in node.names:
                aliases[imported.asname or imported.name] = imported.name
    found = set()
    for node in ast.walk(tree):
        if not isinstance(node, ast.Call):
            continue
        if isinstance(node.func, ast.Name):
            name = aliases.get(node.func.id, node.func.id)
            if name in _CROSS_SECTIONAL or "cross_sectional" in name or "indneutralize" in name:
                found.add(name)
        elif isinstance(node.func, ast.Attribute):
            name = node.func.attr
            if name in {"zscore", "scale", "indneutralize", "zscore_by_group"}:
                found.add(name)
            if name == "rank" and any(
                keyword.arg == "axis" and isinstance(keyword.value, ast.Constant)
                and keyword.value.value in (1, "columns") for keyword in node.keywords
            ):
                found.add("rank(axis=1)")
    return sorted(found)


def _failure_reason(exc: Exception) -> str:
    # Registry errors can embed filesystem paths. Keep the factor ID in the
    # audit entry and expose only a stable reason and the exception class.
    text = str(exc).lower()
    for fragment, reason in (
        (">95% nan", "insufficient_finite_factor_values"),
        ("+/- inf", "non_finite_factor_values"),
        ("output shape", "factor_output_shape_mismatch"),
        ("panel missing", "undeclared_input_unavailable"),
        ("import failed", "native_factor_import_failed"),
    ):
        if fragment in text:
            return reason
    return "native_factor_computation_failed:" + type(exc).__name__


def daily_features(frame: pd.DataFrame, symbol: str) -> tuple[pd.DataFrame, dict]:
    """Consider every native factor; retain only executable single-stock history.

    This stage never uses targets or sample-wide variance/correlation selection.
    Imputation and statistical selection belong to the model's training folds.
    """
    registry = get_default_registry()
    ids = registry.list()
    panel = {
        str(column): pd.DataFrame(
            {symbol: pd.to_numeric(frame[column], errors="coerce")}, index=frame.index
        )
        for column in frame.columns
        if column in {"open", "high", "low", "close", "volume", "amount", "vwap"}
        or str(column).startswith(("fund:", "val:"))
    }
    audit: dict[str, Any] = {
        "source": "Vibe get_default_registry / Registry.compute",
        "universe": "equity_cn", "frequency": "1d", "input_columns": sorted(panel),
        "attempted": [], "eligible": [], "computed": [], "excluded": [],
        "causality_audit": "two historical prefixes, after declared warmup; rtol=1e-8 atol=1e-10",
        "selection": "Applicability and causality only; learned filtering is fitted within training folds.",
    }
    features = {}
    for factor_id in ids:
        audit["attempted"].append({"id": factor_id, "reason": "native_metadata_reviewed"})
        alpha = registry.get(factor_id)
        meta = alpha.meta
        reason = None
        required = meta.get("columns_required", [])
        warmup = int(meta.get("min_warmup_bars", 0))
        if "equity_cn" not in meta.get("universe", []):
            reason = "market_not_equity_cn"
        elif "1d" not in {str(value).lower() for value in meta.get("frequency", [])}:
            reason = "frequency_not_daily"
        elif meta.get("requires_sector"):
            reason = "sector_panel_required"
        elif meta.get("extras_required"):
            reason = "extra_inputs_required:" + ",".join(meta["extras_required"])
        elif missing := sorted(set(required) - set(panel)):
            reason = "missing_observed_columns:" + ",".join(missing)
        elif _UNSUPPORTED_NOTES.search(str(meta.get("notes", ""))):
            reason = "native_notes_mark_degraded_proxy_or_unimplemented"
        elif len(frame) < warmup + 25:
            reason = "insufficient_history_for_warmup_and_causality_audit"
        if reason is None:
            try:
                calls = _cross_sectional_calls(registry.get_source(factor_id))
                if calls:
                    reason = "cross_sectional_panel_required:" + ",".join(calls)
            except Exception as exc:
                reason = "native_source_audit_failed:" + type(exc).__name__
        if reason is not None:
            audit["excluded"].append({"id": factor_id, "reason": reason})
            continue
        audit["eligible"].append({"id": factor_id, "reason": "observed_inputs_and_single_stock_daily_semantics"})
        try:
            values = registry.compute(factor_id, panel)[symbol].reindex(frame.index)
            cuts = sorted({max(warmup + 20, int(len(frame) * fraction)) for fraction in (0.6, 0.8)})
            for cut in cuts:
                prefix = {key: data.iloc[:cut] for key, data in panel.items()}
                previous = registry.compute(factor_id, prefix)[symbol]
                if not np.allclose(
                    values.iloc[warmup:cut].to_numpy(dtype=float),
                    previous.iloc[warmup:cut].to_numpy(dtype=float),
                    rtol=1e-8, atol=1e-10, equal_nan=True,
                ):
                    reason = "historical_prefix_changed_future_information_dependency"
                    break
            if reason is not None:
                audit["excluded"].append({"id": factor_id, "reason": reason})
                continue
        except Exception as exc:
            audit["excluded"].append({"id": factor_id, "reason": _failure_reason(exc)})
            continue
        features[factor_id] = values
        audit["computed"].append({"id": factor_id, "reason": "native_computed_and_prefix_consistent"})
    audit["counts"] = {"registry_total": len(ids), **{
        key: len(audit[key]) for key in ("attempted", "eligible", "computed", "excluded")
    }}
    return pd.DataFrame(features, index=frame.index), audit


def minute_features(frame: pd.DataFrame) -> tuple[pd.DataFrame, dict]:
    """Reuse native causal operators without treating daily factors as minutes."""
    columns = [f"minute_return_{lag}" for lag in (1, 5, 15)] + ["minute_volume_ratio_15"]
    columns += [f"minute_volatility_{window}" for window in (5, 15, 30)]
    columns += [f"minute_price_to_mean_{window}" for window in (5, 15, 30)]
    columns += ["session_position"]
    result = pd.DataFrame(np.nan, index=frame.index, columns=columns)
    # A missing trading minute starts a new causal window. Lunch is contiguous
    # in the source's trading-minute position; overnight always resets state.
    continuous = frame["day"].eq(frame["day"].shift()) & frame["position"].diff().eq(1)
    segments = (~continuous).cumsum()
    for _, positions in frame.groupby(segments, sort=False).indices.items():
        group = frame.iloc[positions]
        close = group[["close"]].astype(float)
        volume = group[["volume"]].astype(float)
        returns = safe_div(delta(close, 1), close.shift(1))
        for lag in (1, 5, 15):
            values = safe_div(delta(close, lag), close.shift(lag)).iloc[:, 0]
            result.loc[group.index, f"minute_return_{lag}"] = values
        result.loc[group.index, "minute_volume_ratio_15"] = safe_div(volume, ts_mean(volume, 15)).iloc[:, 0]
        for window in (5, 15, 30):
            result.loc[group.index, f"minute_volatility_{window}"] = ts_std(returns, window).iloc[:, 0]
            result.loc[group.index, f"minute_price_to_mean_{window}"] = (safe_div(close, ts_mean(close, window)) - 1).iloc[:, 0]
    result["session_position"] = pd.to_numeric(frame["position"], errors="coerce") / 241
    result = result.replace([np.inf, -np.inf], np.nan)
    return result, {
        "source": "Vibe src.factors.base operators; Mona added minute-frequency/session adaptation",
        "frequency": "1min", "native_ops": ["delta", "safe_div", "ts_mean", "ts_std"],
        "daily_factor_library_applied": False, "features": columns,
        "session_reset": "trading day and missing trading-minute gaps",
        "counts": {"computed": len(columns)},
    }

