def _timestamp(value: Any) -> datetime | None:
    if isinstance(value, str) and len(value) == 8 and value.isdigit():
        value = f"{value[:4]}-{value[4:6]}-{value[6:]}"
    try:
        stamp = pd.Timestamp(value)
