    if stamp.tzinfo is None:
        stamp = stamp.tz_localize(_SHANGHAI)
    else:
        stamp = stamp.tz_convert(_SHANGHAI)
    return stamp.to_pydatetime()


def _key(stamp: datetime, interval: str) -> str:
    if interval == "1D":
        return stamp.date().isoformat()
    return stamp.isoformat(timespec="seconds")


def _parse_issued(value: str) -> datetime | None:
    try:
        issued = datetime.fromisoformat(value.replace("Z", "+00:00"))
    except (TypeError, ValueError):
        return None
    if issued.tzinfo is None:
        return None
    return issued.astimezone(UTC)


def _finite_number(value: Any) -> bool:
    return isinstance(value, (int, float)) and not isinstance(value, bool) and math.isfinite(value)


def _validated_result(result: dict[str, Any]) -> tuple[dict[str, Any], str]:
    required = ("symbol", "interval", "status", "as_of", "last_price", "model_version", "data_fingerprint", "points", "evaluation_basis")
    if not isinstance(result, dict) or any(key not in result for key in required):
        raise ValueError("forecast result is missing required fields")
    if result["status"] != "ok" or result["interval"] not in {"1D", "intraday"}:
        raise ValueError("only successful daily or intraday forecasts can be stored")
    if any(not isinstance(result[key], str) or not result[key] for key in ("symbol", "as_of", "model_version", "data_fingerprint")):
        raise ValueError("forecast identity fields must be non-empty strings")
    if result["evaluation_basis"] not in _EVALUATION_BASES:
        raise ValueError("unsupported forecast evaluation basis")
    if not _finite_number(result["last_price"]) or result["last_price"] <= 0:
        raise ValueError("forecast last_price must be finite and positive")
    if not isinstance(result["points"], list):
        raise ValueError("forecast points must be a list")

    seen_steps: set[int] = set()
    for point in result["points"]:
        if not isinstance(point, dict):
            raise ValueError("forecast points must be objects")
        step = point.get("step")
        if not isinstance(step, int) or isinstance(step, bool) or step < 1 or step in seen_steps:
            raise ValueError("forecast steps must be unique positive integers")
        seen_steps.add(step)
        if "lower" not in point or "upper" not in point:
            raise ValueError("forecast points must include both price bounds")
        if not _finite_number(point.get("price")):
            raise ValueError("forecast prices must be finite numbers")
        lower, upper = point["lower"], point["upper"]
        if (lower is None) != (upper is None):
            raise ValueError("forecast price bounds must both be present or both be null")
        if point["price"] <= 0 or (
            lower is not None
            and (not _finite_number(lower) or not _finite_number(upper) or lower <= 0 or upper <= 0 or lower > upper)
        ):
            raise ValueError("forecast price range is invalid")
        if result["interval"] == "intraday" and (not isinstance(point.get("trade_date"), str) or not point["trade_date"]):
            raise ValueError("intraday forecast points require trade_date")

    payload = dict(result)
    identity = json.dumps(
        [result[key] for key in ("model_version", "symbol", "interval", "as_of", "data_fingerprint")],
        ensure_ascii=False,
        separators=(",", ":"),
        allow_nan=False,
    )
    forecast_id = hashlib.sha256(identity.encode("utf-8")).hexdigest()
    return payload, forecast_id


def _observation_rows(observations: pd.DataFrame, interval: str) -> list[tuple[str, datetime, float]]:
    if not isinstance(observations, pd.DataFrame) or "close" not in observations.columns:
        raise ValueError("observations must be a DataFrame with a close column")
    rows: dict[str, tuple[datetime, float]] = {}
    for index, close in zip(observations.index, observations["close"], strict=False):
        stamp = _timestamp(index)
        try:
            price = float(close)
        except (TypeError, ValueError, OverflowError):
            continue
        if stamp is None or not math.isfinite(price) or price <= 0:
            continue
        rows[_key(stamp, interval)] = (stamp, price)
    return [(key, *rows[key]) for key in sorted(rows)]


def _close_equal(left: float, right: float) -> bool:
    return math.isclose(left, right, rel_tol=1e-12, abs_tol=1e-12)


class ForecastStore:
    """SQLite-backed immutable predictions and first-seen forward scores."""

    def __init__(self) -> None:
        self._database = get_runtime_root() / "forecasts.sqlite3"

    @contextmanager
    def _connection(self) -> Iterator[sqlite3.Connection]:
        self._database.parent.mkdir(parents=True, exist_ok=True)
        connection = sqlite3.connect(self._database, timeout=10)
        connection.row_factory = sqlite3.Row
        try:
            connection.execute("PRAGMA foreign_keys = ON")
            connection.executescript(_SCHEMA)
            with connection:
                yield connection
        finally:
            connection.close()

    def get(self, cache_key: str) -> dict[str, Any] | None:
        if not isinstance(cache_key, str) or not cache_key:
            raise ValueError("cache_key must be a non-empty string")
        with self._connection() as connection:
            row = connection.execute(
                """SELECT f.result_json FROM forecast_cache c
                   JOIN forecasts f USING(forecast_id)
                   WHERE c.cache_key = ?
                   ORDER BY f.issued_at DESC, f.forecast_id DESC LIMIT 1""",
                (cache_key,),
            ).fetchone()
        return json.loads(row["result_json"]) if row is not None else None

    def save(self, cache_key: str, result: dict[str, Any]) -> dict[str, Any]:
        if not isinstance(cache_key, str) or not cache_key:
            raise ValueError("cache_key must be a non-empty string")
        payload, forecast_id = _validated_result(result)
        issued_at = _issued_now()
        payload["forecast_id"] = forecast_id
        payload["issued_at"] = issued_at
        encoded = json.dumps(payload, ensure_ascii=False, separators=(",", ":"), allow_nan=False)
        with self._connection() as connection:
            connection.execute(
                "INSERT OR IGNORE INTO forecasts(forecast_id, symbol, interval, issued_at, result_json) VALUES(?,?,?,?,?)",
                (forecast_id, result["symbol"], result["interval"], issued_at, encoded),
            )
            connection.execute("INSERT OR IGNORE INTO forecast_cache(cache_key, forecast_id) VALUES(?,?)", (cache_key, forecast_id))
            row = connection.execute("SELECT result_json FROM forecasts WHERE forecast_id = ?", (forecast_id,)).fetchone()
        return json.loads(row["result_json"])

    def merge_minutes(self, symbol: str, frame: pd.DataFrame) -> pd.DataFrame:
        if not isinstance(symbol, str) or not symbol:
            raise ValueError("symbol must be a non-empty string")
        if not isinstance(frame, pd.DataFrame) or any(column not in frame.columns for column in _MINUTE_COLUMNS):
            raise ValueError("frame must contain trade_date, close, volume, amount, day, and position")

        records: list[tuple[str, str, float, float, float, str, int]] = []
        for trade_date, close, volume, amount, day, position in frame.loc[:, _MINUTE_COLUMNS].itertuples(index=False, name=None):
            try:
                stamp = pd.Timestamp(trade_date)
                close_value, volume_value, amount_value = float(close), float(volume), float(amount)
            except (TypeError, ValueError, OverflowError) as exc:
                raise ValueError("minute observations contain invalid values") from exc
            if pd.isna(stamp) or stamp.tzinfo is None:
                raise ValueError("trade_date must be timezone-aware")
            stamp = stamp.tz_convert(_SHANGHAI)
            if (
                not math.isfinite(close_value)
                or close_value <= 0
                or not math.isfinite(volume_value)
                or volume_value < 0
                or not math.isfinite(amount_value)
                or amount_value < 0
                or not isinstance(day, str)
                or not day
                or not isinstance(position, Integral)
                or isinstance(position, bool)
                or position < 0
            ):
                raise ValueError("minute observations contain invalid values")
            records.append((
                symbol,
                stamp.isoformat(),
                close_value,
                volume_value,
                amount_value,
                day,
                int(position),
            ))

        with self._connection() as connection:
            connection.executemany(
                """INSERT INTO minute_observations(symbol, trade_date, close, volume, amount, day, position)
                   VALUES(?,?,?,?,?,?,?)
                   ON CONFLICT(symbol, trade_date) DO UPDATE SET
                       close = excluded.close,
                       volume = excluded.volume,
                       amount = excluded.amount,
                       day = excluded.day,
                       position = excluded.position
                   WHERE minute_observations.close IS NOT excluded.close
                      OR minute_observations.volume IS NOT excluded.volume
                      OR minute_observations.amount IS NOT excluded.amount
                      OR minute_observations.day IS NOT excluded.day
                      OR minute_observations.position IS NOT excluded.position""",
                records,
            )
            stale_days = connection.execute(
                """SELECT trade_day FROM (
                       SELECT DISTINCT substr(trade_date, 1, 10) AS trade_day
                       FROM minute_observations WHERE symbol = ?
                       ORDER BY trade_day DESC LIMIT -1 OFFSET 20
                   )""",
                (symbol,),
            ).fetchall()
            connection.executemany(
                "DELETE FROM minute_observations WHERE symbol = ? AND substr(trade_date, 1, 10) = ?",
                [(symbol, row["trade_day"]) for row in stale_days],
            )
            rows = connection.execute(
                """SELECT trade_date, close, volume, amount, day, position
                   FROM minute_observations WHERE symbol = ? ORDER BY trade_date""",
                (symbol,),
            ).fetchall()

        result = pd.DataFrame([tuple(row) for row in rows], columns=_MINUTE_COLUMNS)
        if result.empty:
            result = pd.DataFrame({
                "trade_date": pd.Series(dtype="datetime64[ns, Asia/Shanghai]"),
                "close": pd.Series(dtype="float64"),
                "volume": pd.Series(dtype="float64"),
                "amount": pd.Series(dtype="float64"),
                "day": pd.Series(dtype="object"),
                "position": pd.Series(dtype="int64"),
            })
        else:
            result["trade_date"] = pd.to_datetime(result["trade_date"], utc=True).dt.tz_convert(_SHANGHAI)
            result["position"] = result["position"].astype("int64")
        return result.reset_index(drop=True)

    def evaluate(
        self,
        symbol: str,
        interval: str,
        observations: pd.DataFrame,
        *,
        model_version: str | None = None,
    ) -> dict[str, Any]:
        if not isinstance(symbol, str) or not symbol or interval not in {"1D", "intraday"}:
            raise ValueError("symbol and a supported interval are required")
        if model_version is not None and (not isinstance(model_version, str) or not model_version):
            raise ValueError("model_version must be a non-empty string when provided")
        rows = _observation_rows(observations, interval)
        row_by_key = {key: (position, stamp, close) for position, (key, stamp, close) in enumerate(rows)}
        now = datetime.now(UTC)
        scored_at = now.isoformat(timespec="microseconds").replace("+00:00", "Z")
        with self._connection() as connection:
            forecast_query = """SELECT f.forecast_id, f.issued_at, f.result_json FROM forecasts f
                   WHERE f.symbol = ? AND f.interval = ?"""
            parameters: list[str] = [symbol, interval]
            if model_version is not None:
                forecast_query += " AND json_extract(f.result_json, '$.model_version') = ?"
                parameters.append(model_version)
            forecast_query += " ORDER BY f.issued_at DESC, f.forecast_id DESC LIMIT 200"
            forecasts = connection.execute(forecast_query, parameters).fetchall()

            for stored in forecasts:
                forecast_id = stored["forecast_id"]
                issued_at = _parse_issued(stored["issued_at"])
                if issued_at is None:
                    continue
                forecast = json.loads(stored["result_json"])
                as_of_stamp = _timestamp(forecast.get("as_of"))
                if as_of_stamp is None:
                    continue
                as_of_key = _key(as_of_stamp, interval)
                as_of_row = row_by_key.get(as_of_key)
                last_price = float(forecast["last_price"])

                for point in forecast["points"]:
                    step = int(point["step"])
                    if interval == "1D":
                        if as_of_row is None:
                            continue
                        target_position = as_of_row[0] + step
                        if target_position >= len(rows):
                            continue
                        target_key, target_stamp, target_close = rows[target_position]
                        point_date = point.get("trade_date")
                        if point_date is not None:
                            point_stamp = _timestamp(point_date)
                            if point_stamp is None or _key(point_stamp, interval) != target_key:
                                continue
                        target_time = datetime.combine(target_stamp.date(), time(15, 0), _SHANGHAI).astimezone(UTC)
                    else:
                        target_stamp = _timestamp(point["trade_date"])
                        if target_stamp is None or target_stamp.date() != as_of_stamp.date() or target_stamp <= as_of_stamp:
                            continue
                        target_key = _key(target_stamp, interval)
                        target_time = target_stamp.astimezone(UTC)
                        if as_of_row is not None:
                            expected_position = as_of_row[0] + step
                            if expected_position >= len(rows) or rows[expected_position][0] != target_key:
                                continue
                        target_row = row_by_key.get(target_key)
                        target_close = target_row[2] if target_row is not None else None

                    maturity_time = target_time + timedelta(minutes=1) if interval == "intraday" else target_time
                    if issued_at >= target_time or maturity_time > now:
                        continue
                    if as_of_row is None:
                        continue
                    if interval == "intraday":
                        as_of_close = as_of_row[2]
                        target_row = row_by_key.get(target_key)
                        if target_row is None or target_row[0] != as_of_row[0] + step:
                            continue
                        target_close = target_row[2]
                    else:
                        as_of_close = as_of_row[2]
                    if target_close is None:
                        continue

                    predicted_return = float(point["price"]) / last_price - 1.0
                    actual_return = target_close / as_of_close - 1.0
                    lower = point["lower"]
                    upper = point["upper"]
                    lower_return = float(lower) / last_price - 1.0 if lower is not None else None
                    upper_return = float(upper) / last_price - 1.0 if upper is not None else None
                    range_covered = int(lower_return <= actual_return <= upper_return) if lower_return is not None else None
                    connection.execute(
                        """INSERT OR IGNORE INTO forecast_scores(
                               forecast_id, step, target_trade_date, predicted_return, actual_return,
                               actual_price, latest_observed_price, lower_return, upper_return,
                               range_covered, revision_count, scored_at
                           ) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)""",
                        (forecast_id, step, target_key, predicted_return, actual_return,
                         target_close, target_close, lower_return, upper_return, range_covered, 0, scored_at),
                    )
                    existing = connection.execute(
                        "SELECT latest_observed_price FROM forecast_scores WHERE forecast_id = ? AND step = ?",
                        (forecast_id, step),
                    ).fetchone()
                    if existing is not None and not _close_equal(float(existing["latest_observed_price"]), target_close):
                        connection.execute(
                            """UPDATE forecast_scores SET latest_observed_price = ?, revision_count = revision_count + 1
                               WHERE forecast_id = ? AND step = ?""",
                            (target_close, forecast_id, step),
                        )

            forecast_ids = [row["forecast_id"] for row in forecasts]
            scores: list[sqlite3.Row] = []
            if forecast_ids:
                placeholders = ",".join("?" for _ in forecast_ids)
                scores = connection.execute(
                    f"SELECT * FROM forecast_scores WHERE forecast_id IN ({placeholders}) ORDER BY step, scored_at",
                    forecast_ids,
                ).fetchall()

        by_step: dict[int, list[sqlite3.Row]] = {}
        for score in scores:
            by_step.setdefault(int(score["step"]), []).append(score)
        all_steps = sorted(by_step)
        by_horizon: list[dict[str, Any]] = []
        all_errors: list[float] = []
        all_baseline_errors: list[float] = []
        all_coverage: list[int] = []
        for step in all_steps:
            samples = by_step.get(step, [])
            errors = [abs(float(score["predicted_return"]) - float(score["actual_return"])) for score in samples]
            baseline_errors = [abs(float(score["actual_return"])) for score in samples]
            covered = [int(score["range_covered"]) for score in samples if score["range_covered"] is not None]
            all_errors.extend(errors)
            all_baseline_errors.extend(baseline_errors)
            all_coverage.extend(covered)
            by_horizon.append({
                "step": step,
                "samples": len(samples),
                "mae": sum(errors) / len(errors) if errors else None,
                "baseline_mae": sum(baseline_errors) / len(baseline_errors) if baseline_errors else None,
                "coverage": sum(covered) / len(covered) if covered else None,
            })

        revised_points = sum(1 for score in scores if int(score["revision_count"]) > 0)
        latest = max((score["scored_at"] for score in scores), default=None)
        return {
            "status": "tracking" if scores else "waiting",
            "forecasts": len(forecasts),
            "completed_points": len(scores),
            "mae": sum(all_errors) / len(all_errors) if all_errors else None,
            "baseline_mae": sum(all_baseline_errors) / len(all_baseline_errors) if all_baseline_errors else None,
            "coverage": sum(all_coverage) / len(all_coverage) if all_coverage else None,
            "revised_points": revised_points,
            "last_scored_at": latest,
            "by_horizon": by_horizon,
        }
